package com.silverroom.camera;
import java.util.*;import android.opengl.GLES20;
/** Controlled cache, milestones and GPU command traces. Not a phone latency benchmark. */
public final class LensSwitchProbe{
 static List<String> passed=new ArrayList<>();static void check(boolean yes,String name){if(!yes)throw new AssertionError(name);passed.add(name);}
 public static class Memory implements LensStartupCache.Store{Map<String,String> data=new HashMap<>();int writes;public String get(String key){return data.get(key);}public void put(String key,String value){writes++;data.put(key,value);}public void remove(String key){data.remove(key);}public void clear(){data.clear();}}
 public static List<String> run(){
 Memory memory=new Memory();LensStartupCache cache=new LensStartupCache(memory,"firmware-A");LensPlan.Route main=new LensPlan.Route("0",null,23,23,false,false),tele=new LensPlan.Route("4",null,85,85,false,false),bound=new LensPlan.Route("2","4",85,85,false,false);List<LensPlan.Route> routes=Arrays.asList(main,tele,bound);Set<String> failed=new HashSet<>();
 check(cache.route(routes,85,false,failed)==tele&&cache.profile("tele",8)==-1,"Unverified metadata never produces a startup cache hit and retains normal route priority");cache.verified(bound,"tele",5);LensStartupCache restarted=new LensStartupCache(memory,"firmware-A");check(restarted.route(routes,230,false,failed)==bound&&restarted.profile("tele",8)==5,"A proved telephoto route and profile survive an app restart for the same real optical group");int writes=memory.writes;cache.verified(bound,"tele",5);check(memory.writes==writes,"Repeated successful preview sessions do not rewrite unchanged startup values");
 check(cache.route(routes,50,false,failed)==main,"A cached telephoto path cannot substitute for an unrelated main optical request");failed.add(bound.key());check(cache.route(routes,135,false,failed)==tele,"A failed cached route falls back to another candidate of the same physical focal group");failed.add(tele.key());check(cache.route(routes,135,false,failed)==null,"When all telephoto paths fail, cache lookup does not fall back to a main crop");failed.clear();check(cache.route(Arrays.asList(main,tele),85,false,failed)==tele,"A cache hint missing from the current metadata is ignored");
 LensStartupCache firmware=new LensStartupCache(memory,"firmware-B");check(firmware.profile("tele",8)==-1&&firmware.route(routes,85,false,failed)==tele,"Firmware changes isolate old route and stream profiles");check(cache.profile("tele",5)==-1&&cache.profile("other-mode",8)==-1,"Invalid profile indices and different configuration keys cannot reuse an incompatible stream profile");cache.invalidate(bound,"tele");check(cache.profile("tele",8)==-1&&cache.route(routes,85,false,failed)==tele,"A rejected cached profile removes its route hint before full compatibility fallback");cache.verified(bound,"tele",2);cache.clear();check(memory.data.isEmpty()&&cache.profile("tele",8)==-1,"Manual lens re-detection clears only the dedicated startup cache");
 LensSwitchTrace trace=new LensSwitchTrace();trace.begin(23,85,1000,1016);trace.mark("设备已打开",1080);trace.mark("设备已打开",1100);trace.mark("真实取景已就绪",1170);trace.end(1180);String report=trace.report();check(report.contains("23 → 85mm")&&report.contains("调度：+16ms")&&report.contains("设备已打开：+80ms")&&report.contains("首帧已绘制：+180ms"),"Switch diagnostics measure queued, open, readiness and rendered milestones on one monotonic timeline");trace.mark("过期回调",1300);check(!trace.running()&&!trace.report().contains("过期回调"),"A completed switch timeline ignores late callbacks");trace.begin(85,14,1500,1500);trace.cancel();trace.mark("后台回调",1700);check(!trace.report().contains("后台回调")&&!trace.report().contains("设备已打开"),"A new or cancelled switch does not retain the previous switch stages");
 PreviewTransition transition=new PreviewTransition();GLES20.version=10;transition.hold(300,400);int copies=GLES20.copies;transition.hold(300,400);check(GLES20.copies==copies,"Repeated waiting-frame draws keep one GPU snapshot without repeated copies");PreviewHold live=new PreviewHold();GLES20.version=11;live.save(300,400);check(transition.blend(300,400,2000,true)&&GLES20.presented==10,"The first real new frame begins a GPU overlay from the retained old-lens image");check(transition.blend(300,400,2060,true)&&Math.abs(GLES20.opacity-.5f)<.001&&!GLES20.blend&&GLES20.unit==GLES20.GL_TEXTURE0,"The 120ms blend reaches half opacity and restores blend and texture-unit state");check(live.draw(300,400)&&GLES20.presented==11,"The live capture hold retains the new raw preview instead of the transitional composite");check(!transition.blend(300,400,2120,true),"The optical crossfade finishes after 120ms without delaying readiness or capture");
 transition.hold(300,400);check(!transition.blend(300,400,3000,false),"Reduced-motion mode presents the new live image without a timed fade");transition.hold(300,400);check(!transition.blend(400,300,4000,true),"A resized viewport rejects an old transition texture instead of stretching it");transition.hold(300,400);transition.clear();check(!transition.blend(300,400,5000,true),"Pause, error and still-capture cleanup cannot revive a private retained transition frame");return passed;
 }
}
